INSERT INTO dashboard_domain_registry(domain,kind,rule_version) SELECT domain,'SHARED',2
 FROM unnest(ARRAY['yahoo.co.uk','yahoo.co.in','ymail.com','rocketmail.com','msn.com',
 'hotmail.co.uk','outlook.co.uk','live.co.uk','mail.com','email.com','gmx.com','gmx.de',
 'web.de','fastmail.com','hey.com','pm.me','tuta.com','tutanota.com','qq.com','163.com',
 '126.com','yandex.com','yandex.ru','mail.ru','comcast.net','att.net','sbcglobal.net',
 'verizon.net','cox.net','earthlink.net','bellsouth.net','optonline.net','btinternet.com',
 'sendgrid.net','amazonses.com','mailgun.org','mailgun.net','mandrillapp.com',
 'rsgsv.net','mcdlv.net','mailchimp.com','ccsend.com','constantcontact.com',
