-- Use the longest PSL match; exception rules remove one suffix label.
-- Unknown suffixes stay separate. Never guess a boundary by taking the last two labels.
CREATE FUNCTION dashboard_organization_domain(host TEXT) RETURNS TEXT LANGUAGE plpgsql STABLE STRICT AS $$
DECLARE labels TEXT[]; suffix TEXT; i INTEGER; n INTEGER; suffix_size INTEGER:=0;
        exception_size INTEGER; dedicated TEXT;
BEGIN
 labels:=string_to_array(host,'.'); n:=cardinality(labels);
 FOR i IN 1..n LOOP
   suffix:=array_to_string(labels[i:n],'.');
   IF EXISTS(SELECT 1 FROM dashboard_domain_registry WHERE domain=suffix AND kind='SHARED') THEN RETURN NULL; END IF;
   IF EXISTS(SELECT 1 FROM dashboard_domain_registry WHERE domain=suffix AND kind='DEDICATED') THEN dedicated:=suffix; END IF;
 END LOOP;
 IF dedicated IS NOT NULL THEN RETURN dedicated; END IF;
 FOR i IN 1..n LOOP
   suffix:=array_to_string(labels[i:n],'.');
   IF EXISTS(SELECT 1 FROM dashboard_public_suffix_rules WHERE domain=suffix AND kind='EXCEPTION') THEN exception_size:=n-i; END IF;
   IF EXISTS(SELECT 1 FROM dashboard_public_suffix_rules WHERE domain=suffix AND kind='EXACT') THEN suffix_size:=greatest(suffix_size,n-i+1); END IF;
   IF i>1 AND EXISTS(SELECT 1 FROM dashboard_public_suffix_rules WHERE domain=suffix AND kind='WILDCARD') THEN suffix_size:=greatest(suffix_size,n-i+2); END IF;
 END LOOP;
 suffix_size:=COALESCE(exception_size,suffix_size);
 IF suffix_size=0 OR n<=suffix_size THEN RETURN NULL; END IF;
 RETURN array_to_string(labels[n-suffix_size:n],'.');
END $$;

CREATE OR REPLACE FUNCTION dashboard_assign_unit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE k TEXT; kind_value TEXT; group_key_value TEXT; label_value TEXT; unit_value BIGINT; group_value BIGINT; organization TEXT;
BEGIN
 PERFORM id FROM user_accounts WHERE id=NEW.account_id FOR KEY SHARE;
 kind_value:=COALESCE(NEW.dashboard_unit_kind,'MESSAGE');
 k:=COALESCE(NEW.dashboard_unit_key,NEW.provider_message_id);
 group_key_value:=lower(kind_value)||':'||k;
 label_value:=CASE WHEN kind_value='MESSAGE' THEN
   COALESCE(NULLIF(NEW.from_display_name,''),NULLIF(NEW.from_address,''),'Unknown sender') ELSE k END;
 IF kind_value='ADDRESS' THEN
   organization:=dashboard_organization_domain(split_part(k,'@',2));
   IF organization IS NOT NULL THEN group_key_value:='domain:'||organization; label_value:=organization; END IF;
 END IF;
 INSERT INTO sender_units(account_id,kind,canonical_key,automatic_group_key,automatic_label,evidence_reason)
 VALUES(NEW.account_id,kind_value,k,group_key_value,label_value,
   CASE WHEN organization IS NOT NULL THEN 'Organization domain and subdomains (PSL v2)'
     ELSE COALESCE(NEW.dashboard_identity_reason,'Retained identity needs fresh metadata') END)
 ON CONFLICT(account_id,kind,canonical_key) DO UPDATE SET canonical_key=EXCLUDED.canonical_key
 RETURNING id INTO unit_value;
 INSERT INTO sender_groups(account_id,group_key,label) VALUES(NEW.account_id,group_key_value,label_value)
 ON CONFLICT(account_id,group_key) DO UPDATE SET group_key=EXCLUDED.group_key RETURNING id INTO group_value;
 INSERT INTO sender_group_members VALUES(NEW.account_id,unit_value,group_value)
 ON CONFLICT(account_id,unit_id) DO NOTHING;
 INSERT INTO message_sender_units VALUES(NEW.account_id,NEW.id,unit_value)
 ON CONFLICT(account_id,metadata_id) DO UPDATE SET unit_id=EXCLUDED.unit_id;
 RETURN NEW;
END $$;

-- Reclassify indexed atomic addresses without refetching mail or changing message IDs.
-- Manual membership stays fixed; the new baseline is available when a correction resets.
CREATE TEMP TABLE dashboard_regroup ON COMMIT DROP AS
 SELECT u.id,u.account_id,u.automatic_group_key AS old_key,
   COALESCE('domain:'||d.organization,'address:'||u.canonical_key) AS new_key,
   COALESCE(d.organization,u.canonical_key) AS label
 FROM sender_units u CROSS JOIN LATERAL
   (SELECT dashboard_organization_domain(split_part(u.canonical_key,'@',2)) AS organization) d
 WHERE u.kind='ADDRESS';
DELETE FROM dashboard_regroup WHERE old_key=new_key;
INSERT INTO sender_groups(account_id,group_key,label)
 SELECT DISTINCT account_id,new_key,label FROM dashboard_regroup
 ON CONFLICT(account_id,group_key) DO NOTHING;
UPDATE sender_group_members member SET group_id=g.id FROM dashboard_regroup r,sender_groups g,sender_groups old
 WHERE member.account_id=r.account_id AND member.unit_id=r.id
 AND old.account_id=r.account_id AND old.id=member.group_id AND old.group_key=r.old_key
 AND g.account_id=r.account_id AND g.group_key=r.new_key;
UPDATE sender_units u SET automatic_group_key=r.new_key,automatic_label=r.label,
 evidence_reason=CASE WHEN r.new_key LIKE 'domain:%' THEN 'Organization domain and subdomains (PSL v2)' ELSE 'Shared or unknown domain; exact address' END
 FROM dashboard_regroup r WHERE u.id=r.id;
INSERT INTO dashboard_account_settings(account_id,grouping_revision,rule_version)
 SELECT DISTINCT account_id,1,2 FROM dashboard_regroup
 ON CONFLICT(account_id) DO UPDATE SET grouping_revision=dashboard_account_settings.grouping_revision+1,rule_version=2;
-- Revision checks expire unconfirmed previews; confirmed job targets remain immutable.
